-- Migration 003: Add avatar column to users table
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS avatar_url VARCHAR(512) DEFAULT NULL;

/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs, in order,
 * each filename it would apply.
 *
 * Ordering rules
 * ──────────────
 * Files are sorted lexicographically by filename, so the conventional numeric
 * prefix scheme (001_, 002_, …) naturally produces the correct run order.
 *
 * Usage
 * ─────
 *   node migrate.js                 # default: ./migrations/
 *   node migrate.js ./other/path/   # custom migrations directory
 */

"use strict";

const fs   = require("fs");
const path = require("path");

// ─── Configuration ────────────────────────────────────────────────────────────

/** Directory that contains the SQL migration files. */
const MIGRATIONS_DIR = path.resolve(process.argv[2] || "./migrations");

/** Only files whose names match this pattern are treated as migrations. */
const MIGRATION_FILE_PATTERN = /^.+\.sql$/i;

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns a list of migration filenames (not full paths) found in `dir`,
 * filtered to SQL files and sorted lexicographically (ascending).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of migration filenames.
 */
function getMigrationFiles(dir) {
  let entries;
  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    if (err.code === "ENOTDIR") {
      throw new Error(`Path is not a directory: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter((name) => {
      // Keep only files (skip sub-directories) that match the naming pattern.
      const fullPath = path.join(dir, name);
      const stat     = fs.statSync(fullPath);
      return stat.isFile() && MIGRATION_FILE_PATTERN.test(name);
    })
    .sort(); // lexicographic ascending → respects numeric prefixes
}

/**
 * Pretty-prints a divider line of a given width.
 *
 * @param {number} [width=60]
 */
function printDivider(width = 60) {
  console.log("─".repeat(width));
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log();
  printDivider();
  console.log(" Database Migration Runner");
  printDivider();
  console.log(` Migrations directory : ${MIGRATIONS_DIR}`);

  // ── Discover files ──────────────────────────────────────────────────────────
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log("\n No migration files found — nothing to apply.");
    printDivider();
    console.log();
    return;
  }

  console.log(` Migrations found     : ${files.length}`);
  printDivider();
  console.log();

  // ── Log each file in order ──────────────────────────────────────────────────
  files.forEach((filename, index) => {
    const order    = String(index + 1).padStart(String(files.length).length, "0");
    const fullPath = path.join(MIGRATIONS_DIR, filename);

    console.log(`  [${order}] Applying migration : ${filename}`);
    console.log(`       Full path          : ${fullPath}`);
    console.log();
  });

  // ── Summary ─────────────────────────────────────────────────────────────────
  printDivider();
  console.log(` ${files.length} migration(s) would be applied.`);
  printDivider();
  console.log();
}

main();

