// ─── Configuration ────────────────────────────────────────────────────────────

/** Directory that contains the SQL migration files. */
const MIGRATIONS_DIR = path.resolve(process.argv[2] || "./migrations");

/** Only files whose names match this pattern are treated as migrations. */
const MIGRATION_FILE_PATTERN = /^.+\.sql$/i;

/** Path to the env file that must supply DATABASE_URL. */
const ENV_FILE = path.resolve(".env.test");

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parses a .env file and returns its key/value pairs as a plain object.
 *
 * Supported syntax
 * ────────────────
 *  • `KEY=value`            plain value
 *  • `KEY="value"`          double-quoted value (quotes are stripped)
 *  • `KEY='value'`          single-quoted value (quotes are stripped)
 *  • `# comment`            full-line comment (ignored)
 *  • inline `# comment`     text after an unquoted `#` is ignored
 *  • blank lines            ignored
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {{ [key: string]: string }} Parsed key/value map.
 * @throws {Error} If the file cannot be read.
 */
function loadEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const result = {};

  for (const rawLine of raw.split(/\r?\n/)) {
    // Strip leading/trailing whitespace, skip blanks and full-line comments.
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;

    // Split on the first `=` only — values may contain `=` themselves.
    const eqIdx = line.indexOf("=");
    if (eqIdx === -1) continue; // malformed line — no `=` found, skip it

    const key      = line.slice(0, eqIdx).trim();
    let   rawValue = line.slice(eqIdx + 1).trim();

    // Strip matching surrounding quotes.
    if (
      (rawValue.startsWith('"') && rawValue.endsWith('"')) ||
      (rawValue.startsWith("'") && rawValue.endsWith("'"))
    ) {
      rawValue = rawValue.slice(1, -1);
    } else {
      // Remove an inline comment (unquoted `#` preceded by whitespace).
      const commentIdx = rawValue.search(/\s+#/);
      if (commentIdx !== -1) {
        rawValue = rawValue.slice(0, commentIdx).trim();
      }
    }

    if (key) result[key] = rawValue;
  }

  return result;
}

/**
 * Reads DATABASE_URL from the given env-variable map, validates it, and
 * returns a redacted version safe for logging (password replaced with `***`).
 *
 * @param {{ [key: string]: string }} env  - Key/value map from loadEnvFile.
 * @param {string}                   src  - Source filename (used in errors).
 * @returns {{ raw: string, redacted: string }}
 * @throws {Error} If DATABASE_URL is absent or cannot be parsed as a URL.
 */
function resolveConnectionString(env, src) {
  const raw = env["DATABASE_URL"];

  if (!raw) {
    throw new Error(`DATABASE_URL is not defined in ${src}`);
  }

  // Validate that the value is a well-formed URL and redact the password.
  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    throw new Error(
      `DATABASE_URL in ${src} is not a valid URL: "${raw}"`
    );
  }

  // Build the redacted string only when a password is actually present.
  let redacted = raw;
  if (parsed.password) {
    parsed.password = "***";
    redacted = parsed.toString();
  }

  return { raw, redacted };
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log();
  printDivider();
  console.log(" Database Migration Runner");
  printDivider();

  // ── Resolve connection string ───────────────────────────────────────────────
  let connectionString;
  try {
    const env = loadEnvFile(ENV_FILE);
    const { raw, redacted } = resolveConnectionString(env, ENV_FILE);
    connectionString = raw; // would be passed to a real DB client
    console.log(` Env file             : ${ENV_FILE}`);
    console.log(` Connection string    : ${redacted}`);
    console.log(` [OK] Connected successfully to database.`);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  printDivider();
  console.log(` Migrations directory : ${MIGRATIONS_DIR}`);

