-- Migration 003: Add role column to users
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS role VARCHAR(50) NOT NULL DEFAULT 'user';

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs the
 * filename of each migration it would apply, in lexicographic (numeric)
 * order.
 *
 * Usage:
 *   node migrate.js
 *
 * Design notes:
 *  - Files are sorted lexicographically so that numeric prefixes such as
 *    001_, 002_, 003_ determine a stable, predictable order.
 *  - Only files with a .sql extension are considered; any other files
 *    present in the directory are silently skipped.
 *  - The script uses only Node.js built-in modules (fs and path) so no
 *    dependencies need to be installed.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ───────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Returns an alphabetically sorted list of .sql filenames found in `dir`.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (basename only).
 * @throws {Error} If the directory cannot be read.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    if (err.code === 'EACCES') {
      throw new Error(`Permission denied reading migrations directory: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter((entry) => {
      // Only include regular files with a .sql extension.
      const fullPath = path.join(dir, entry);
      const stat     = fs.statSync(fullPath);
      return stat.isFile() && path.extname(entry).toLowerCase() === SQL_EXTENSION;
    })
    .sort(); // lexicographic sort — relies on numeric filename prefixes (e.g. 001_)
}

/**
 * Logs the ordered list of migrations that would be applied.
 *
 * @param {string[]} files - Sorted array of migration filenames.
 */
function logMigrationPlan(files) {
  if (files.length === 0) {
    console.log('No migration files found — nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach((filename, index) => {
    const position = String(index + 1).padStart(String(files.length).length, '0');
    console.log(`  [${position}] ${filename}`);
  });

  console.log('\nDone — migration plan logged. No changes have been applied.');
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log(`Migration runner starting…`);
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  try {
    const sqlFiles = getSqlFiles(MIGRATIONS_DIR);
    logMigrationPlan(sqlFiles);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }
}

main();

