/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs
 * the filenames in the order they would be applied (lexicographic /
 * numeric prefix order).
 *
 * Usage:
 *   node migrate.js             # dry-run: log filenames only
 *   node migrate.js --dry-run   # same explicit flag
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of absolute paths to every *.sql file inside
 * `dir`, sorted lexicographically so that numeric prefixes
 * (001_, 002_, …) guarantee the correct application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of absolute file paths.
 */
function collectMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry => entry.name)
    .sort(); // lexicographic sort honours numeric prefixes when zero-padded

  return sqlFiles.map(name => path.join(dir, name));
}

/**
 * Reads a single migration file and returns its contents as a string.
 *
 * @param {string} filePath - Absolute path to the .sql file.
 * @returns {string} SQL content.
 */
function readMigrationFile(filePath) {
  return fs.readFileSync(filePath, 'utf8');
}

// ─── Core logic ───────────────────────────────────────────────────────────────

/**
 * Iterates over every discovered migration file, logs the filename,
 * and (in a real implementation) would execute the SQL against a
 * database connection.
 *
 * @param {object} [options]
 * @param {boolean} [options.dryRun=true] - When true, only log; never execute.
 */
function runMigrations({ dryRun = true } = {}) {
  console.log('='.repeat(55));
  console.log('  Database Migration Runner');
  console.log(`  Mode   : ${dryRun ? 'dry-run (log only)' : 'live'}`);
  console.log(`  Source : ${MIGRATIONS_DIR}`);
  console.log('='.repeat(55));

  // 1. Discover files
  let migrationFiles;
  try {
    migrationFiles = collectMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (migrationFiles.length === 0) {
    console.log('[INFO]  No migration files found. Nothing to apply.');
    return;
  }

  console.log(`[INFO]  Found ${migrationFiles.length} migration file(s).\n`);

  // 2. Process each file in order
  migrationFiles.forEach((filePath, index) => {
    const filename  = path.basename(filePath);
    const stepLabel = `[${String(index + 1).padStart(3, '0')}]`;

    // Always log the filename that would be applied
    console.log(`${stepLabel} Applying: ${filename}`);

    if (dryRun) {
      // Dry-run: read the file to confirm it is readable, but do not execute
      try {
        const sql = readMigrationFile(filePath);
        const lineCount = sql.split('\n').length;
        console.log(`       Preview  : ${lineCount} line(s) — OK (dry-run, not executed)\n`);
      } catch (err) {
        console.error(`       [ERROR] Could not read file: ${err.message}\n`);
      }
    } else {
      /**
       * Live execution would go here, e.g.:
       *
       *   const sql = readMigrationFile(filePath);
       *   await db.query(sql);
       *   await db.query(
       *     'INSERT INTO schema_migrations (filename, applied_at) VALUES ($1, NOW())',
       *     [filename]
       *   );
       *
       * A real runner would also:
       *   • Skip already-applied migrations (check schema_migrations table).
       *   • Wrap each migration in a transaction.
       *   • Roll back and halt on failure.
       */
      console.log('       [SKIPPED] Live execution not wired up in this script.\n');
    }
  });

  console.log('='.repeat(55));
  console.log(`  ${dryRun ? 'Dry-run complete' : 'Migration complete'} — ${migrationFiles.length} file(s) processed.`);
  console.log('='.repeat(55));
}

// ─── Entry point ──────────────────────────────────────────────────────────────

const isDryRun = !process.argv.includes('--live');
runMigrations({ dryRun: isDryRun });

