/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs
 * the filenames in the order they would be applied (lexicographic /
 * numeric prefix order).
 *
 * Connection string resolution:
 *   Reads DATABASE_URL from a .env file (defaults to .env.test) and
 *   logs a simulated successful connection message. The password
 *   component is always redacted before logging.
 *
 * Usage:
 *   node migrate.js                        # dry-run, uses .env.test
 *   node migrate.js --env-file .env.local  # dry-run, custom env file
 *   node migrate.js --live                 # live mode (DB execution placeholder)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// Resolve the env file path from --env-file <path>, or fall back to .env.test
const envFileFlagIndex = process.argv.indexOf('--env-file');
const ENV_FILE = path.resolve(
  __dirname,
  envFileFlagIndex !== -1 && process.argv[envFileFlagIndex + 1]
    ? process.argv[envFileFlagIndex + 1]
    : '.env.test'
);

// ─── Env-file parser ─────────────────────────────────────────────────────────

/**
 * Parses a .env-style file and returns a plain object of key→value pairs.
 * Handles:
 *   - Blank lines and lines beginning with # (comments) are ignored.
 *   - Optional surrounding quotes (' or ") are stripped from values.
 *   - Only the first `=` on each line is treated as the delimiter so that
 *     values which themselves contain `=` (e.g. Base64 strings) are preserved.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const raw = fs.readFileSync(filePath, 'utf8');
  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; // malformed line — no `=` present

    const key   = trimmed.slice(0, eqIndex).trim();
    let   value = trimmed.slice(eqIndex + 1).trim();

    // Strip optional wrapping quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) result[key] = value;
  }

  return result;
}

/**
 * Replaces the password segment of a postgres:// (or postgresql://) URL
 * with `****` so credentials are never exposed in log output.
 *
 * Input  → postgres://user:s3cr3t@host:5432/db
 * Output → postgres://user:****@host:5432/db
 *
 * If the URL cannot be parsed the entire string is replaced with
 * `<unparseable-url>` as a safe fallback.
 *
 * @param {string} connStr - Raw connection string.
 * @returns {string} Redacted connection string safe for logging.
 */
function redactConnectionString(connStr) {
  try {
    const url      = new URL(connStr);
    url.password   = url.password ? '****' : '';
    return url.toString();
  } catch {
    return '<unparseable-url>';
  }
}

/**
 * Resolves DATABASE_URL from the env file and logs a simulated
 * successful connection message (no real network call is made).
 *
 * @param {string} envFilePath - Absolute path to the .env file.
 * @returns {string} The raw (unredacted) DATABASE_URL for internal use.
 */
function resolveAndLogConnection(envFilePath) {
  console.log(`[DB]    Reading env file : ${path.basename(envFilePath)}`);

  let env;
  try {
    env = parseEnvFile(envFilePath);
  } catch (err) {
    throw new Error(`Failed to parse env file — ${err.message}`);
  }

  const databaseUrl = env['DATABASE_URL'];
  if (!databaseUrl) {
    throw new Error(`DATABASE_URL is not defined in ${path.basename(envFilePath)}`);
  }

  const redacted = redactConnectionString(databaseUrl);
  console.log(`[DB]    Target           : ${redacted}`);
  console.log('[DB]    Connection       : OK (simulated — no real connection made)');

  return databaseUrl; // returned but never logged in raw form
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

