#!/usr/bin/env node
/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs
 * the filenames in the order they would be applied (lexicographic /
 * numeric order, which matches the NNN_ prefix convention).
 *
 * Naming convention expected:
 *   <zero-padded-number>_<description>.sql
 *   e.g. 001_create_users.sql, 002_create_posts.sql
 *
 * Usage:
 *   node migrate.js               # dry-run — logs filenames only
 *   node migrate.js --verbose     # also prints each file's SQL content
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const VERBOSE        = process.argv.includes('--verbose');

// ── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when a filename looks like a valid migration file.
 * Accepts any *.sql file whose name starts with one or more digits.
 *
 * @param {string} filename
 * @returns {boolean}
 */
function isMigrationFile(filename) {
  return /^\d+.*\.sql$/i.test(filename);
}

/**
 * Comparator that sorts migration filenames in ascending lexicographic order.
 * Because the numeric prefix is zero-padded this also gives correct numeric
 * ordering (001 < 002 < … < 099 < 100).
 *
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function byMigrationOrder(a, b) {
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
}

// ── Core logic ────────────────────────────────────────────────────────────────

/**
 * Collects, sorts, and logs every SQL migration file found in MIGRATIONS_DIR.
 * Throws descriptive errors for common problems (missing directory, empty
 * directory, unreadable files) so callers / CI pipelines get clear feedback.
 */
function runMigrations() {
  // 1. Verify the migrations directory exists --------------------------------
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    throw new Error(
      `Migrations directory not found: ${MIGRATIONS_DIR}\n` +
      'Create the directory and add at least one *.sql file.'
    );
  }

  // 2. Read directory entries ------------------------------------------------
  const allEntries = fs.readdirSync(MIGRATIONS_DIR);

  const migrationFiles = allEntries
    .filter(isMigrationFile)
    .sort(byMigrationOrder);

  if (migrationFiles.length === 0) {
    console.warn(
      `[migrate] WARNING — no SQL migration files found in: ${MIGRATIONS_DIR}`
    );
    return;
  }

  // 3. Log each file in order ------------------------------------------------
  console.log(`[migrate] Found ${migrationFiles.length} migration(s) in: ${MIGRATIONS_DIR}`);
  console.log('[migrate] Applying migrations in the following order:\n');

  migrationFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const position = String(index + 1).padStart(3, '0');

    console.log(`  [${position}] ${filename}`);

    // Optional: print the SQL content when --verbose is passed
    if (VERBOSE) {
      const sql = fs.readFileSync(filePath, 'utf8').trim();
      console.log('       ┌─ SQL ──────────────────────────────────────────');
      sql.split('\n').forEach(line => console.log(`       │ ${line}`));
      console.log('       └────────────────────────────────────────────────\n');
    }
  });

  console.log('\n[migrate] Dry-run complete. No changes were made to the database.');
  console.log('[migrate] Connect a database client and execute each file above to apply them.');
}

// ── Entry point ───────────────────────────────────────────────────────────────

try {
  runMigrations();
} catch (err) {
  console.error(`[migrate] ERROR — ${err.message}`);
  process.exit(1);
}

