#!/usr/bin/env node

/**
 * migrate.js
 *
 * Scans ./migrations/ for *.sql files, sorts them in lexicographic (version)
 * order, and logs each filename it would apply.
 *
 * Usage:
 *   node migrate.js               # dry-run: lists every pending migration
 *   node migrate.js --dir <path>  # override the migrations directory
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

const DEFAULT_MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

/**
 * Parse a minimal set of CLI flags.
 * Supports:  --dir <path>
 * @returns {{ migrationsDir: string }}
 */
function parseArgs(argv) {
  const args = argv.slice(2); // drop 'node' and script name
  let migrationsDir = DEFAULT_MIGRATIONS_DIR;

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--dir' && args[i + 1]) {
      migrationsDir = path.resolve(args[++i]);
    }
  }

  return { migrationsDir };
}

// ---------------------------------------------------------------------------
// Core logic
// ---------------------------------------------------------------------------

/**
 * Return all *.sql filenames from `dir`, sorted lexicographically so that
 * numeric prefixes (001_, 002_, …) produce the correct application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]}  Sorted array of bare filenames (not full paths).
 * @throws  {Error}     If the directory cannot be read.
 */
function getSortedMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Could not read migrations directory: ${err.message}`);
  }

  return entries
    .filter(name => name.endsWith('.sql'))
    .sort(); // lexicographic sort; relies on numeric prefix convention
}

/**
 * Log every migration file that would be applied, in order.
 *
 * @param {string}   migrationsDir - Resolved path to the migrations directory.
 */
function runDryRun(migrationsDir) {
  console.log(`\nMigration runner — dry run`);
  console.log(`Directory : ${migrationsDir}\n`);

  const files = getSortedMigrationFiles(migrationsDir);

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration file(s) to apply:\n`);

  files.forEach((filename, index) => {
    const filePath = path.join(migrationsDir, filename);
    const stats    = fs.statSync(filePath);
    const sizeKB   = (stats.size / 1024).toFixed(2);

    console.log(
      `  [${String(index + 1).padStart(3, '0')}]  ${filename}  (${sizeKB} KB)`
    );
  });

  console.log('\nDry run complete — no changes were made to the database.\n');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

(function main() {
  const { migrationsDir } = parseArgs(process.argv);

  try {
    runDryRun(migrationsDir);
  } catch (err) {
    console.error(`\nError: ${err.message}\n`);
    process.exit(1);
  }
})();

