#!/usr/bin/env node

/**
 * migrate.js
 *
 * Scans ./migrations/ for *.sql files, sorts them in lexicographic (version)
 * order, and logs each filename it would apply.
 *
 * Reads DATABASE_URL from a .env file to resolve the target database and logs
 * a simulated connection message (no real connection is made).
 *
 * Usage:
 *   node migrate.js                          # uses .env in cwd
 *   node migrate.js --dir <path>             # override migrations directory
 *   node migrate.js --env-file <path>        # override .env file location
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

const DEFAULT_MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const DEFAULT_ENV_FILE       = path.resolve(__dirname, '.env.test');

/**
 * Parse a minimal set of CLI flags.
 * Supports:  --dir <path>  --env-file <path>
 *
 * @param {string[]} argv
 * @returns {{ migrationsDir: string, envFile: string }}
 */
function parseArgs(argv) {
  const args = argv.slice(2); // drop 'node' and script name
  let migrationsDir = DEFAULT_MIGRATIONS_DIR;
  let envFile       = DEFAULT_ENV_FILE;

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--dir' && args[i + 1]) {
      migrationsDir = path.resolve(args[++i]);
    } else if (args[i] === '--env-file' && args[i + 1]) {
      envFile = path.resolve(args[++i]);
    }
  }

  return { migrationsDir, envFile };
}

// ---------------------------------------------------------------------------
// .env parsing
// ---------------------------------------------------------------------------

/**
 * Parse a .env file and return its key/value pairs as a plain object.
 *
 * Rules:
 *  - Lines beginning with '#' (ignoring leading whitespace) are comments.
 *  - Blank lines are skipped.
 *  - Each valid line must match:  KEY=VALUE  (no spaces around '=').
 *  - Only DATABASE_URL is consumed by this script; all other keys are parsed
 *    but never accessed, logged, or forwarded anywhere.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>}
 * @throws {Error} If the file cannot be read.
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw new Error(`Could not read env file: ${err.message}`);
  }

  const result = {};
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue; // skip blanks / comments

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; // malformed line — skip silently

    const key   = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();
    result[key] = value;
  }

  return result;
}

/**
 * Retrieve DATABASE_URL from a parsed env object, throwing a clear error if
 * it is absent or empty.
 *
 * @param {Record<string, string>} env
 * @returns {string}
 */
function resolveDatabaseUrl(env) {
  const url = env['DATABASE_URL'];
  if (!url) {
    throw new Error(
      'DATABASE_URL is not set in the env file. ' +
      'Add DATABASE_URL=<connection-string> and retry.'
    );
  }
  return url;
}

// ---------------------------------------------------------------------------
// Connection-string formatting (safe, non-secret output only)
// ---------------------------------------------------------------------------

/**
 * Parse a postgres:// connection URL and return only the non-secret
 * structural parts suitable for logging: host, port, and database name.
 * The password (and username, which can also be sensitive) are replaced
 * with "***" so that nothing secret ever appears in output.
 *
 * Supports the standard form:
 *   postgres[ql]://[user[:password]@]host[:port][/database][?options]
 *
 * @param {string} rawUrl
 * @returns {{ host: string, port: string, database: string, redactedUrl: string }}
 */
function parseConnectionUrl(rawUrl) {
  let parsed;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new Error(`DATABASE_URL is not a valid URL.`);
  }

  const supportedProtocols = ['postgres:', 'postgresql:'];
  if (!supportedProtocols.includes(parsed.protocol)) {
    throw new Error(
      `Unsupported database protocol "${parsed.protocol}". ` +
      'Expected postgres:// or postgresql://'
    );
  }

  const host     = parsed.hostname || 'localhost';
  const port     = parsed.port     || '5432';
  const database = parsed.pathname.replace(/^\//, '') || '(default)';

  // Build a fully redacted URL safe to surface in logs
  const redactedUrl = `${parsed.protocol}//${host}:${port}/${database}`;

  return { host, port, database, redactedUrl };
}

// ---------------------------------------------------------------------------
// Core migration logic
// ---------------------------------------------------------------------------

/**
 * Return all *.sql filenames from `dir`, sorted lexicographically so that
 * numeric prefixes (001_, 002_, …) produce the correct application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]}  Sorted array of bare filenames (not full paths).
 * @throws  {Error}     If the directory cannot be read.
 */
function getSortedMigrationFiles(dir) {
  let entries;
  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Could not read migrations directory: ${err.message}`);
  }

  return entries
    .filter(name => name.endsWith('.sql'))
    .sort(); // lexicographic — relies on numeric prefix convention (001_, 002_, …)
}

/**
 * Simulate connecting to the database and log the outcome.
 * No real network call or driver is used.
 *
 * @param {string} rawUrl - The raw DATABASE_URL value (used only internally
 *                          to extract safe metadata; never logged verbatim).
 */
function logSimulatedConnection(rawUrl) {
  const { host, port, database, redactedUrl } = parseConnectionUrl(rawUrl);

  console.log(`  Target    : ${redactedUrl}`);
  console.log(`  Host      : ${host}`);
  console.log(`  Port      : ${port}`);
  console.log(`  Database  : ${database}`);
  console.log(`  Status    : connected (simulated)\n`);
}

/**
 * Main dry-run: resolve the connection string, then log every migration file
 * that would be applied, in order.
 *
 * @param {string} migrationsDir - Resolved path to the migrations directory.
 * @param {string} envFile       - Resolved path to the .env file.
 */
function runDryRun(migrationsDir, envFile) {
  console.log(`\nMigration runner — dry run`);
  console.log(`Env file  : ${envFile}`);
  console.log(`Directory : ${migrationsDir}\n`);

  // --- Step 1: resolve DATABASE_URL ---
  console.log(`[1/2] Resolving database connection…`);
  const env         = parseEnvFile(envFile);
  const databaseUrl = resolveDatabaseUrl(env);   // raw value — not logged
  logSimulatedConnection(databaseUrl);

  // --- Step 2: list migration files ---
  console.log(`[2/2] Scanning for migration files…\n`);
  const files = getSortedMigrationFiles(migrationsDir);

  if (files.length === 0) {
    console.log('  No migration files found.');
    return;
  }

  console.log(`  Found ${files.length} migration file(s) to apply:\n`);
  files.forEach((filename, index) => {
    const filePath = path.join(migrationsDir, filename);
    const stats    = fs.statSync(filePath);
    const sizeKB   = (stats.size / 1024).toFixed(2);

    console.log(
      `    [${String(index + 1).padStart(3, '0')}]  ${filename}  (${sizeKB} KB)`
    );
  });

  console.log('\nDry run complete — no changes were made to the database.\n');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

(function main() {
  const { migrationsDir, envFile } = parseArgs(process.argv);

  try {
    runDryRun(migrationsDir, envFile);
  } catch (err) {
    console.error(`\nError: ${err.message}\n`);
    process.exit(1);
  }
})();

