#!/usr/bin/env node

/**
 * migrate.js
 *
 * Reads all .sql files from the ./migrations/ directory and logs each
 * filename it would apply, in lexicographic (numeric-prefix) order.
 *
 * Usage:
 *   node migrate.js
 *
 * Conventions expected of migration files:
 *   - Stored in ./migrations/ relative to this script.
 *   - Named with a numeric prefix so they sort deterministically, e.g.:
 *       001_create_users.sql
 *       002_create_posts.sql
 *   - Must have a .sql extension; all other files are ignored.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every .sql filename inside `dir`, sorted lexicographically.
 * Lexicographic order matches numeric order when filenames share a
 * zero-padded numeric prefix (001_, 002_, …).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of .sql filenames (basename only).
 * @throws {Error} If the directory cannot be read.
 */
function getMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Could not read migrations directory: ${err.message}`);
  }

  const sqlFiles = entries.filter(
    (filename) =>
      path.extname(filename).toLowerCase() === SQL_EXTENSION &&
      fs.statSync(path.join(dir, filename)).isFile()         // skip sub-dirs
  );

  // Lexicographic sort — deterministic and zero-pad friendly.
  sqlFiles.sort((a, b) => a.localeCompare(b));

  return sqlFiles;
}

/**
 * Validates that a filename follows the expected naming convention:
 * one or more digits, an underscore, a descriptive name, and .sql.
 * Logs a warning if the convention is not followed (non-fatal).
 *
 * @param {string} filename
 */
function warnIfUnconventional(filename) {
  const CONVENTION = /^\d+_.+\.sql$/i;
  if (!CONVENTION.test(filename)) {
    console.warn(
      `  [WARN] "${filename}" does not follow the ` +
      `recommended naming convention: <number>_<description>.sql`
    );
  }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  // 1. Discover migration files.
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  // 2. Guard: nothing to do.
  if (files.length === 0) {
    console.log('No .sql migration files found. Nothing to apply.');
    return;
  }

  // 3. Log each file that would be applied, in order.
  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach((filename, index) => {
    warnIfUnconventional(filename);

    const filePath     = path.join(MIGRATIONS_DIR, filename);
    const { size }     = fs.statSync(filePath);
    const paddedIndex  = String(index + 1).padStart(2, '0');

    console.log(`  [${paddedIndex}/${String(files.length).padStart(2, '0')}] ${filename}  (${size} bytes)`);
  });

  console.log('\nDry-run complete. No changes were made to the database.');
  console.log('Integrate a database client to execute these files in order.');
}

main();

