#!/usr/bin/env node
/**
 * migrate.js
 *
 * Reads *.sql files from the ./migrations/ directory and logs each filename
 * it would apply, in lexicographic (numeric-prefix) order.
 *
 * Usage:
 *   node migrate.js              # dry-run: logs filenames only
 *   node migrate.js --verbose    # also prints the SQL content of each file
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const args           = process.argv.slice(2);
const VERBOSE        = args.includes('--verbose');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of absolute paths to every *.sql file inside `dir`,
 * sorted lexicographically so that numeric prefixes (001_, 002_, …) give
 * a deterministic application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]}
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry => entry.name)
    .sort(); // lexicographic — relies on numeric prefixes like 001_, 002_, …

  if (sqlFiles.length === 0) {
    throw new Error(`No .sql files found in: ${dir}`);
  }

  return sqlFiles;
}

/**
 * Logs a section divider with an optional label.
 *
 * @param {string} [label]
 */
function divider(label = '') {
  const line = '─'.repeat(60);
  console.log(label ? `\n${line}\n  ${label}\n${line}` : line);
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('🗄️  Database Migration Runner (dry-run mode)');
  divider();
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);
  console.log(`Verbose output       : ${VERBOSE}`);
  divider();

  // 1. Discover migration files
  let sqlFiles;
  try {
    sqlFiles = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`\n❌  Error: ${err.message}`);
    process.exit(1);
  }

  console.log(`Found ${sqlFiles.length} migration file(s):\n`);

  // 2. Log each file in order
  sqlFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const stepNum  = String(index + 1).padStart(2, '0');

    console.log(`  [${stepNum}] ${filename}`);

    if (VERBOSE) {
      // Read and indent the SQL for display purposes only
      try {
        const sql = fs.readFileSync(filePath, 'utf8').trimEnd();
        const indented = sql
          .split('\n')
          .map(line => `       │  ${line}`)
          .join('\n');
        console.log(indented);
        console.log();
      } catch (err) {
        console.error(`       └─ ❌  Could not read file: ${err.message}`);
      }
    }
  });

  divider();
  console.log(
    `\n✅  Dry run complete — ${sqlFiles.length} migration(s) would be applied in the order above.`
  );
  console.log('    To execute for real, wire each file\'s contents to your database client.\n');
}

main();

