#!/usr/bin/env node

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename it would apply, in lexicographic (version) order.
 *
 * Usage:
 *   node migrate.js
 *
 * Naming convention for migration files:
 *   <version>_<description>.sql   e.g. 001_create_users.sql
 *
 * The files are sorted lexicographically so a consistent numeric prefix
 * (001, 002, 003 …) guarantees the correct application order.
 */

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every *.sql filename inside `dir`, sorted lexicographically.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of SQL filenames (basename only).
 * @throws {Error} If the directory cannot be read.
 */
function getSortedMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Failed to read migrations directory: ${err.message}`);
  }

  return entries
    .filter(file => path.extname(file).toLowerCase() === SQL_EXTENSION)
    .sort();  // lexicographic — relies on numeric prefix for ordering
}

/**
 * Reads a single SQL file and returns its contents as a string.
 *
 * @param {string} filePath - Absolute path to the SQL file.
 * @returns {string} The raw SQL text.
 * @throws {Error} If the file cannot be read.
 */
function readMigrationFile(filePath) {
  try {
    return fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    throw new Error(`Failed to read migration file "${filePath}": ${err.message}`);
  }
}

// ─── Core runner ──────────────────────────────────────────────────────────────

/**
 * Discovers all pending migration files and logs the order in which they
 * would be applied, together with a preview of each file's content.
 *
 * In a real implementation this function would:
 *   1. Connect to the database.
 *   2. Query an applied-migrations tracking table.
 *   3. Skip already-applied files.
 *   4. Execute each pending file inside a transaction.
 *   5. Record the applied migration in the tracking table.
 */
function runMigrations() {
  console.log('=== Database Migration Runner ===\n');
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);

  // ── Discover files ──────────────────────────────────────────────────────────
  const files = getSortedMigrationFiles(MIGRATIONS_DIR);

  if (files.length === 0) {
    console.log('\nNo migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration file(s).\n`);
  console.log('─'.repeat(50));

  // ── Log each file in order ──────────────────────────────────────────────────
  files.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const sql      = readMigrationFile(filePath);
    const lines    = sql.trim().split('\n');

    console.log(`[${index + 1}/${files.length}] Applying : ${filename}`);
    console.log(`            Path     : ${filePath}`);
    console.log(`            Size     : ${Buffer.byteLength(sql, 'utf8')} bytes, ${lines.length} line(s)`);
    console.log(`            Preview  : ${lines[0].trim()}`);  // first non-empty line
    console.log('─'.repeat(50));
  });

  console.log('\nDry-run complete. All migrations listed above would be applied in order.');
  console.log('Connect this runner to a database client to execute them for real.');
}

// ─── Entry point ──────────────────────────────────────────────────────────────

try {
  runMigrations();
} catch (err) {
  console.error(`\n[ERROR] ${err.message}`);
  process.exit(1);
}

