 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Directory that contains the migration files. */
const MIGRATIONS_DIR = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.join(__dirname, 'migrations');

/** .env file from which DATABASE_URL is resolved. */
const ENV_FILE = path.join(__dirname, '.env.test');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parses a .env file and returns its key/value pairs as a plain object.
 * Supports:
 *   - KEY=value
 *   - KEY="value"  /  KEY='value'   (quotes are stripped)
 *   - Lines starting with # are treated as comments and ignored.
 *   - Blank lines are ignored.
 *
 * @param {string} envPath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 * @throws {Error} If the file cannot be read.
 */
function parseEnvFile(envPath) {
  let raw;
  try {
    raw = fs.readFileSync(envPath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${envPath}`);
    }
    throw err;
  }

  return raw
    .split('\n')
    .reduce((acc, line) => {
      const trimmed = line.trim();
      // Skip blank lines and comments.
      if (!trimmed || trimmed.startsWith('#')) return acc;

      const eqIndex = trimmed.indexOf('=');
      if (eqIndex === -1) return acc; // malformed line — skip

      const key   = trimmed.slice(0, eqIndex).trim();
      let   value = trimmed.slice(eqIndex + 1).trim();

      // Strip optional surrounding quotes.
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }

      acc[key] = value;
      return acc;
    }, {});
}

/**
 * Resolves DATABASE_URL from the env file and returns a safe descriptor
 * object containing only the non-sensitive parts of the URL (protocol,
 * host, port, database name). Credentials are intentionally omitted so
 * they are never surfaced in logs.
