 * @throws {Error} If DATABASE_URL is missing or cannot be parsed.
 */
function resolveDbConnection() {
  const env = parseEnvFile(ENV_FILE);

  if (!env.DATABASE_URL) {
    throw new Error(`DATABASE_URL not found in ${ENV_FILE}`);
  }

  let parsed;
  try {
    parsed = new URL(env.DATABASE_URL);
  } catch {
    throw new Error('DATABASE_URL in env file is not a valid URL.');
  }

  return {
    protocol : parsed.protocol.replace(':', ''),        // e.g. "postgres"
    host     : parsed.hostname,                          // e.g. "db.internal"
    port     : parsed.port || '5432',                    // default PG port
    database : parsed.pathname.replace(/^\//, '') || '', // strip leading "/"
  };
}

/**
 * Returns all *.sql filenames inside `dir`, sorted in ascending
 * lexicographic order (e.g. 001_…, 002_…, 003_…).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of SQL filenames (basenames only).
 * @throws {Error} If the directory cannot be read.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
