    console.log('\nNo SQL migration files found. Nothing to apply.');
    return;
  }

  console.log(`Migrations found     : ${files.length}`);
  console.log('-'.repeat(60));

  // 3. Iterate in order, logging each file as it would be applied.
  files.forEach((filename, index) => {
    const stepNumber = String(index + 1).padStart(
      String(files.length).length, // keep numbering width consistent
      '0'
    );

    // Read the file to confirm it is accessible and non-empty.
    const sql = readMigration(MIGRATIONS_DIR, filename);
