/**
 * migrate.js
 *
 * Database migration runner.
 *
 * Reads all *.sql files from the ./migrations/ directory, sorts them
 * into lexicographic (alphabetical) order — which preserves the
 * numeric prefix convention (001_, 002_, …) — and logs each filename
 * it would apply.
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every *.sql filename found in `dir`, sorted lexicographically.
 * Throws a descriptive error when the directory cannot be read.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of SQL filenames (basename only).
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && path.extname(entry.name) === SQL_EXTENSION)
    .map(entry => entry.name)
    .sort(); // lexicographic sort keeps 001_ < 002_ < … ordering

  return sqlFiles;
}

/**
 * Logs each migration filename that would be applied, in order.
 * No SQL is executed — this is a dry-run / planning step.
 *
 * @param {string[]} files - Ordered list of SQL filenames to log.
 */
function logMigrations(files) {
  if (files.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${files.length} migration file(s) in: ${MIGRATIONS_DIR}\n`);
  console.log('Migrations to apply (in order):');
  console.log('─'.repeat(48));

  files.forEach((filename, index) => {
    const step = String(index + 1).padStart(2, '0');
    console.log(`  [${step}] ${filename}`);
  });

  console.log('─'.repeat(48));
  console.log(`\nTotal: ${files.length} migration(s) ready to apply.`);
}

// ── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');

  let sqlFiles;

  try {
    sqlFiles = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  logMigrations(sqlFiles);
}

main();

