  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith(SQL_EXTENSION))
    .map(entry => entry.name)
    .sort(); // lexicographic sort — numeric prefixes keep things ordered

  if (sqlFiles.length === 0) {
    throw new Error(`No ${SQL_EXTENSION} files found in ${dir}`);
  }

