#!/usr/bin/env node

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename it would apply, in lexicographic (version) order.
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dir ./custom/migrations   # override migrations directory
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Resolve the migrations directory from a CLI flag or fall back to default. */
function resolveMigrationsDir() {
  const dirFlagIndex = process.argv.indexOf('--dir');
  if (dirFlagIndex !== -1) {
    const customDir = process.argv[dirFlagIndex + 1];
    if (!customDir || customDir.startsWith('--')) {
      console.error('ERROR: --dir flag requires a path argument.');
      process.exit(1);
    }
    return path.resolve(customDir);
  }
  return path.resolve(__dirname, 'migrations');
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Returns all *.sql files inside `dir`, sorted lexicographically so that
 * numeric prefixes (001_, 002_, …) guarantee the correct application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of absolute file paths.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`ERROR: Migrations directory not found: ${dir}`);
    } else if (err.code === 'EACCES') {
      console.error(`ERROR: Permission denied reading directory: ${dir}`);
    } else {
      console.error(`ERROR: Could not read migrations directory: ${err.message}`);
    }
    process.exit(1);
  }

  const sqlFiles = entries
    .filter(name => name.endsWith('.sql'))  // only SQL files
    .sort();                                 // lexicographic = version order

  return sqlFiles.map(name => path.join(dir, name));
}

/**
 * Reads and validates an individual migration file, returning its contents.
 *
 * @param {string} filePath - Absolute path to the .sql file.
 * @returns {string} The raw SQL content of the file.
 */
function readMigrationFile(filePath) {
  try {
    return fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'EACCES') {
      console.error(`  ERROR: Permission denied reading file: ${filePath}`);
    } else {
      console.error(`  ERROR: Could not read file ${filePath}: ${err.message}`);
    }
    process.exit(1);
  }
}

// ---------------------------------------------------------------------------
// Core runner
// ---------------------------------------------------------------------------

/**
 * Discovers all migration files and logs the filename (and a content preview)
 * for each one, in the order they would be applied.
 */
function runMigrations() {
  const migrationsDir = resolveMigrationsDir();

  console.log('='.repeat(60));
  console.log('  Database Migration Runner (dry-run / log mode)');
  console.log('='.repeat(60));
  console.log(`  Migrations directory : ${migrationsDir}`);

  const filePaths = getSqlFiles(migrationsDir);

  if (filePaths.length === 0) {
    console.log('\n  No .sql migration files found. Nothing to apply.\n');
    console.log('='.repeat(60));
    return;
  }

  console.log(`  Files found          : ${filePaths.length}`);
  console.log('='.repeat(60));
  console.log();

  filePaths.forEach((filePath, index) => {
    const filename = path.basename(filePath);
    const sql      = readMigrationFile(filePath);
    const lines    = sql.trim().split('\n');

    // Build a short preview: first non-empty line, max 60 chars.
    const preview  = lines.find(l => l.trim().length > 0) ?? '';
    const truncated = preview.length > 60
      ? `${preview.slice(0, 57)}...`
      : preview;

    console.log(`  [${String(index + 1).padStart(2, '0')}] Applying : ${filename}`);
    console.log(`       Preview  : ${truncated}`);
    console.log(`       Size     : ${Buffer.byteLength(sql, 'utf8')} bytes`);
    console.log();
  });

  console.log('='.repeat(60));
  console.log(`  Done — ${filePaths.length} migration(s) would be applied in the order above.`);
  console.log('='.repeat(60));
  console.log();
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

runMigrations();

