#!/usr/bin/env node
/**
 * migrate.js
 *
 * Reads all .sql files from the ./migrations/ directory and logs each filename
 * it would apply, in lexicographic (numeric-prefix) order.
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dir ./custom_migrations   # override migrations directory
 *
 * Exit codes:
 *   0 – success (including "nothing to migrate")
 *   1 – fatal error (directory missing, unreadable, etc.)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Resolve the migrations directory from CLI args or fall back to the default. */
function resolveMigrationsDir () {
  const dirFlagIndex = process.argv.indexOf('--dir');
  if (dirFlagIndex !== -1 && process.argv[dirFlagIndex + 1]) {
    return path.resolve(process.argv[dirFlagIndex + 1]);
  }
  return path.resolve(__dirname, 'migrations');
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Returns every *.sql file inside `dir`, sorted lexicographically so that
 * numeric prefixes (001_, 002_, …) define the natural application order.
 *
 * @param {string} dir  Absolute path to the migrations directory.
 * @returns {string[]}  Sorted array of full file paths.
 * @throws  {Error}     If the directory cannot be read.
 */
function getSortedMigrationFiles (dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    if (err.code === 'EACCES') {
      throw new Error(`Permission denied reading directory: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(name => name.endsWith('.sql'))   // only SQL files
    .sort()                                  // lexicographic ⟹ numeric order
    .map(name => path.join(dir, name));      // absolute paths for later use
}

/**
 * Pretty-prints a log line with a timestamp prefix.
 *
 * @param {string} level    'INFO' | 'WARN' | 'ERROR'
 * @param {string} message
 */
function log (level, message) {
  const ts = new Date().toISOString();
  console.log(`[${ts}] [${level.padEnd(5)}] ${message}`);
}

// ---------------------------------------------------------------------------
// Core
// ---------------------------------------------------------------------------

/**
 * Main entry point.  Discovers migration files and logs each one that would
 * be applied (in order).  No database connection is made — this is the
 * "dry-run / planning" phase.
 */
function run () {
  const migrationsDir = resolveMigrationsDir();

  log('INFO', `Migrations directory : ${migrationsDir}`);

  // ── Discover files ──────────────────────────────────────────────────────
  let migrationFiles;
  try {
    migrationFiles = getSortedMigrationFiles(migrationsDir);
  } catch (err) {
    log('ERROR', err.message);
    process.exit(1);
  }

  if (migrationFiles.length === 0) {
    log('WARN', 'No .sql files found in migrations directory — nothing to apply.');
    process.exit(0);
  }

  // ── Log what would be applied ───────────────────────────────────────────
  log('INFO', `Found ${migrationFiles.length} migration file(s) to apply:`);

  migrationFiles.forEach((filePath, index) => {
    const filename = path.basename(filePath);
    log('INFO', `  [${String(index + 1).padStart(3, '0')}] ${filename}`);
  });

  log('INFO', 'Migration plan complete — no changes made (dry-run mode).');
}

// ---------------------------------------------------------------------------
// Run
// ---------------------------------------------------------------------------

run();

