    ADD COLUMN IF NOT EXISTS avatar_url VARCHAR(512) DEFAULT NULL;

/**
 * migrate.js
 *
 * Scans ./migrations/ for *.sql files, sorts them into deterministic order,
 * and logs each filename it would apply — oldest migration first.
 *
 * Ordering rules (applied in priority order):
 *   1. Any leading numeric prefix (e.g. "001", "20240101120000") is compared
 *      numerically so that "002" < "010" rather than "010" < "002" (string sort).
 *   2. When two filenames share the same numeric prefix the remainder is
 *      compared alphabetically as a tie-breaker.
 *   3. Files with no numeric prefix sort after all prefixed files,
 *      then alphabetically among themselves.
 */

"use strict";

const fs   = require("fs");
const path = require("path");

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, "migrations");
const SQL_EXTENSION  = ".sql";

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Splits a filename into a [numericPrefix, remainder] tuple so that files
 * can be sorted numerically rather than lexicographically.
 *
 * Examples
 *   "001_create_users.sql"        → [1,   "create_users.sql"]
 *   "20240101_add_column.sql"     → [20240101, "add_column.sql"]
 *   "no_prefix_migration.sql"     → [Infinity, "no_prefix_migration.sql"]
 *
 * @param {string} filename
 * @returns {[number, string]}
 */
function splitPrefix(filename) {
  const match = filename.match(/^(\d+)[_\-]?(.*)/);
  if (match) {
    return [parseInt(match[1], 10), match[2]];
  }
  return [Infinity, filename];
}

/**
 * Comparator that orders migration filenames correctly.
 *
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function compareMigrations(a, b) {
  const [numA, restA] = splitPrefix(a);
  const [numB, restB] = splitPrefix(b);

  if (numA !== numB) {
    return numA - numB;           // numeric ascending
  }
  return restA.localeCompare(restB); // alphabetical tie-breaker
}

/**
 * Reads the migrations directory and returns a sorted list of .sql filenames.
 *
 * @param {string} dir  Absolute path to the migrations directory.
 * @returns {string[]}  Sorted filenames (not full paths).
 * @throws  {Error}     If the directory cannot be read.
 */
function getMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter((file) => path.extname(file).toLowerCase() === SQL_EXTENSION)
    .sort(compareMigrations);
}

// ─── Main ─────────────────────────────────────────────────────────────────────

/**
 * Entry point.  Discovers and logs every migration that would be applied.
 */
function main() {
  console.log("=".repeat(60));
  console.log("  Database Migration Runner");
  console.log("=".repeat(60));
  console.log(`  Migrations directory: ${MIGRATIONS_DIR}`);
  console.log("=".repeat(60));

  let migrationFiles;

  try {
    migrationFiles = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (migrationFiles.length === 0) {
    console.log("\n[INFO] No SQL migration files found. Nothing to apply.");
    return;
  }

  console.log(`\n[INFO] Found ${migrationFiles.length} migration(s) to apply:\n`);

  migrationFiles.forEach((filename, index) => {
    const filePath  = path.join(MIGRATIONS_DIR, filename);
    const fileStats = fs.statSync(filePath);
    const sizeKB    = (fileStats.size / 1024).toFixed(2);

    console.log(
      `  [${String(index + 1).padStart(3, "0")}]  ${filename}  (${sizeKB} KB)`
    );
  });

  console.log("\n" + "=".repeat(60));
  console.log(
    `  ${migrationFiles.length} migration(s) listed. ` +
    "Connect a DB client here to execute them."
  );
  console.log("=".repeat(60) + "\n");
}

main();

